     1→// FV-Lang WASM - C ABI (wasm-bindgen 없음)
     2→// FreeLang mini-wasm-pack 호환
     3→
     4→use std::alloc::{alloc as sys_alloc, dealloc as sys_dealloc, Layout};
     5→
     6→// ── 메모리 관리 ──────────────────────────────
     7→#[no_mangle]
     8→pub extern "C" fn alloc(size: usize) -> *mut u8 {
     9→    let layout = Layout::from_size_align(size, 1).unwrap();
    10→    unsafe { sys_alloc(layout) }
    11→}
    12→
    13→#[no_mangle]
    14→pub extern "C" fn dealloc(ptr: *mut u8, size: usize) {
    15→    let layout = Layout::from_size_align(size, 1).unwrap();
    16→    unsafe { sys_dealloc(ptr, layout) }
    17→}
    18→
    19→// ── 결과 직렬화 헬퍼 ─────────────────────────
    20→// 반환 형식: [4바이트 길이(LE)] + [JSON 바이트]
    21→// JS는 읽은 뒤 dealloc(ptr, 4 + len) 호출 필요
    22→fn write_result(s: &str) -> *mut u8 {
    23→    let bytes = s.as_bytes();
    24→    let len = bytes.len();
    25→    let total = 4 + len;
    26→    // size=0 레이아웃은 UB이므로 최소 1 보장
    27→    let alloc_size = total.max(1);
    28→    let layout = Layout::from_size_align(alloc_size, 1).unwrap();
    29→    unsafe {
    30→        let ptr = sys_alloc(layout);
    31→        let len_bytes = (len as u32).to_le_bytes();
    32→        ptr.copy_from(len_bytes.as_ptr(), 4);
    33→        if len > 0 {
    34→            ptr.add(4).copy_from(bytes.as_ptr(), len);
    35→        }
    36→        ptr
    37→    }
    38→}
    39→
    40→// JS에서 dealloc 호출 시 필요한 size 계산
    41→// dealloc(ptr, result_total_size(ptr)) 으로 호출
    42→#[no_mangle]
    43→pub extern "C" fn result_total_size(ptr: *const u8) -> usize {
    44→    let len = unsafe {
    45→        let mut b = [0u8; 4];
    46→        std::ptr::copy_nonoverlapping(ptr, b.as_mut_ptr(), 4);
    47→        u32::from_le_bytes(b) as usize
    48→    };
    49→    4 + len
    50→}
    51→
    52→// ── 문자열 읽기 헬퍼 ─────────────────────────
    53→unsafe fn read_str(ptr: *const u8, len: usize) -> &'static str {
    54→    let slice = std::slice::from_raw_parts(ptr, len);
    55→    std::str::from_utf8_unchecked(slice)
    56→}
    57→
    58→// ── FV-Lang 코드 평가 ────────────────────────
    59→#[no_mangle]
    60→pub extern "C" fn eval_fv_raw(ptr: *const u8, len: usize) -> *mut u8 {
    61→    let code = unsafe { read_str(ptr, len) };
    62→    let result = run_fv(code);
    63→    write_result(&result)
    64→}
    65→
    66→// ── AST 파싱 ────────────────────────────────
    67→#[no_mangle]
    68→pub extern "C" fn parse_to_ast_raw(ptr: *const u8, len: usize) -> *mut u8 {
    69→    let code = unsafe { read_str(ptr, len) };
    70→    let ast = parse_ast(code);
    71→    write_result(&ast)
    72→}
    73→
    74→// ── 버전 문자열 (null 종료) ───────────────────
    75→#[no_mangle]
    76→pub extern "C" fn fv_version_raw() -> *const u8 {
    77→    b"FV-Lang 0.1.0 (WASM)\0".as_ptr()
    78→}
    79→
    80→// ── 내부 구현 ────────────────────────────────
    81→fn run_fv(code: &str) -> String {
    82→    let lexer = match fv_lang::Lexer::new(code) {
    83→        Ok(l) => l,
    84→        Err(e) => return format!(r#"{{"success":false,"error":"Lexer 오류: {}"}}"#, e),
    85→    };
    86→    let tokens = match lexer.tokenize() {
    87→        Ok(t) => t,
    88→        Err(e) => return format!(r#"{{"success":false,"error":"토큰 오류: {}"}}"#, e),
    89→    };
    90→    let parser = match fv_lang::Parser::new(tokens) {
    91→        Ok(p) => p,
    92→        Err(e) => return format!(r#"{{"success":false,"error":"파서 초기화 오류: {}"}}"#, e),
    93→    };
    94→    let ast = match parser.parse() {
    95→        Ok(a) => a,
    96→        Err(e) => return format!(r#"{{"success":false,"error":"파싱 오류: {}"}}"#, e),
    97→    };
    98→    match fv_lang::CodeGenerator::new().generate(&ast) {
    99→        Ok(out) => format!(r#"{{"success":true,"output":{}}}"#, json_str(&out)),
   100→        Err(e)  => format!(r#"{{"success":false,"error":"컴파일 오류: {}"}}"#, e),
   101→    }
   102→}
   103→
   104→fn parse_ast(code: &str) -> String {
   105→    let lexer = match fv_lang::Lexer::new(code) {
   106→        Ok(l) => l,
   107→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   108→    };
   109→    let tokens = match lexer.tokenize() {
   110→        Ok(t) => t,
   111→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   112→    };
   113→    let parser = match fv_lang::Parser::new(tokens) {
   114→        Ok(p) => p,
   115→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   116→    };
   117→    match parser.parse() {
   118→        Ok(ast) => {
   119→            let debug_str = format!("{:#?}", ast);
   120→            format!(r#"{{"success":true,"ast":{}}}"#, json_str(&debug_str))
   121→        }
   122→        Err(e) => format!(r#"{{"success":false,"error":"{}"}}"#, e),
   123→    }
   124→}
   125→
   126→fn json_str(s: &str) -> String {
   127→    let mut out = String::with_capacity(s.len() + 2);
   128→    out.push('"');
   129→    for c in s.chars() {
   130→        match c {
   131→            '\\' => out.push_str("\\\\"),
   132→            '"'  => out.push_str("\\\""),
   133→            '\n' => out.push_str("\\n"),
   134→            '\r' => out.push_str("\\r"),
   135→            '\t' => out.push_str("\\t"),
   136→            '\x00'..='\x1f' => {
   137→                out.push_str(&format!("\\u{:04x}", c as u32));
   138→            }
   139→            _ => out.push(c),
   140→        }
   141→    }
   142→    out.push('"');
   143→    out
   144→}
