     1→// Lexer: Source code → Tokens
     2→// Tokenizes FV-Lang source code into a stream of tokens
     3→// Security hardened with input validation and resource limits
     4→
     5→use crate::CompileError;
     6→
     7→// Security limits
     8→const MAX_INPUT_SIZE: usize = 10_000_000;        // 10MB max
     9→const MAX_IDENTIFIER_LENGTH: usize = 10_000;     // 10K chars max
    10→const MAX_STRING_LENGTH: usize = 1_000_000;      // 1MB max
    11→const MAX_NUMBER_LENGTH: usize = 100;            // 100 digits max
    12→
    13→#[derive(Debug, Clone, PartialEq)]
    14→pub enum Token {
    15→    // Keywords
    16→    Fn,
    17→    Let,
    18→    If,
    19→    Else,
    20→    Match,
    21→    Return,
    22→    Type,
    23→    Mut,
    24→
    25→    // Identifiers and literals
    26→    Identifier(String),
    27→    Integer(i64),
    28→    Float(f64),
    29→    String(String),
    30→    True,
    31→    False,
    32→
    33→    // Operators
    34→    Plus,
    35→    Minus,
    36→    Star,
    37→    Slash,
    38→    Percent,
    39→    Assign,
    40→    Eq,
    41→    Ne,
    42→    Lt,
    43→    Le,
    44→    Gt,
    45→    Ge,
    46→    And,
    47→    Or,
    48→    Not,
    49→    Arrow,      // ->
    50→    FatArrow,   // =>
    51→    Pipe,       // |
    52→
    53→    // Delimiters
    54→    LParen,
    55→    RParen,
    56→    LBrace,
    57→    RBrace,
    58→    LBracket,
    59→    RBracket,
    60→    Comma,
    61→    Dot,
    62→    Colon,
    63→    Semicolon,
    64→
    65→    // Special
    66→    Eof,
    67→}
    68→
    69→pub struct Lexer {
    70→    input: Vec<char>,
    71→    pos: usize,
    72→    line: usize,
    73→    column: usize,
    74→}
    75→
    76→impl Lexer {
    77→    /// Create a new lexer with input size validation
    78→    pub fn new(input: &str) -> Result<Self, CompileError> {
    79→        // ✅ Check input size
    80→        if input.len() > MAX_INPUT_SIZE {
    81→            return Err(CompileError::LexerError(format!(
    82→                "Input too large: {} bytes (max {} bytes)",
    83→                input.len(),
    84→                MAX_INPUT_SIZE
    85→            )));
    86→        }
    87→
    88→        // ✅ Check for null bytes (security)
    89→        if input.contains('\0') {
    90→            return Err(CompileError::LexerError(
    91→                "Input contains null bytes".to_string(),
    92→            ));
    93→        }
    94→
    95→        Ok(Lexer {
    96→            input: input.chars().collect(),
    97→            pos: 0,
    98→            line: 1,
    99→            column: 1,
   100→        })
   101→    }
   102→
   103→    pub fn tokenize(mut self) -> Result<Vec<Token>, CompileError> {
   104→        let mut tokens = Vec::new();
   105→
   106→        while self.pos < self.input.len() {
   107→            // Skip whitespace
   108→            if let Some(c) = self.current_char() {
   109→                if c.is_whitespace() {
   110→                    if c == '\n' {
   111→                        self.line += 1;
   112→                        self.column = 1;
   113→                    } else {
   114→                        self.column += 1;
   115→                    }
   116→                    self.advance();
   117→                    continue;
   118→                }
   119→            }
   120→
   121→            // Comments
   122→            if self.peek_chars(2) == "//" {
   123→                self.skip_line_comment();
   124→                continue;
   125→            }
   126→
   127→            match self.current_char() {
   128→                Some(c) if c.is_alphabetic() || c == '_' => {
   129→                    tokens.push(self.read_identifier_or_keyword()?);
   130→                }
   131→                Some(c) if c.is_numeric() => {
   132→                    tokens.push(self.read_number()?);
   133→                }
   134→                Some('"') => {
   135→                    tokens.push(self.read_string()?);
   136→                }
   137→                Some('+') => {
   138→                    tokens.push(Token::Plus);
   139→                    self.advance();
   140→                }
   141→                Some('-') => {
   142→                    if self.peek_chars(2) == "->" {
   143→                        tokens.push(Token::Arrow);
   144→                        self.pos += 2;
   145→                        self.column += 2;
   146→                    } else {
   147→                        tokens.push(Token::Minus);
   148→                        self.advance();
   149→                    }
   150→                }
   151→                Some('*') => {
   152→                    tokens.push(Token::Star);
   153→                    self.advance();
   154→                }
   155→                Some('/') => {
   156→                    tokens.push(Token::Slash);
   157→                    self.advance();
   158→                }
   159→                Some('%') => {
   160→                    tokens.push(Token::Percent);
   161→                    self.advance();
   162→                }
   163→                Some('=') => {
   164→                    if self.peek_chars(2) == "==" {
   165→                        tokens.push(Token::Eq);
   166→                        self.pos += 2;
   167→                        self.column += 2;
   168→                    } else if self.peek_chars(2) == "=>" {
   169→                        tokens.push(Token::FatArrow);
   170→                        self.pos += 2;
   171→                        self.column += 2;
   172→                    } else {
   173→                        tokens.push(Token::Assign);
   174→                        self.advance();
   175→                    }
   176→                }
   177→                Some('!') => {
   178→                    if self.peek_chars(2) == "!=" {
   179→                        tokens.push(Token::Ne);
   180→                        self.pos += 2;
   181→                        self.column += 2;
   182→                    } else {
   183→                        tokens.push(Token::Not);
   184→                        self.advance();
   185→                    }
   186→                }
   187→                Some('<') => {
   188→                    if self.peek_chars(2) == "<=" {
   189→                        tokens.push(Token::Le);
   190→                        self.pos += 2;
   191→                        self.column += 2;
   192→                    } else {
   193→                        tokens.push(Token::Lt);
   194→                        self.advance();
   195→                    }
   196→                }
   197→                Some('>') => {
   198→                    if self.peek_chars(2) == ">=" {
   199→                        tokens.push(Token::Ge);
   200→                        self.pos += 2;
   201→                        self.column += 2;
   202→                    } else {
   203→                        tokens.push(Token::Gt);
   204→                        self.advance();
   205→                    }
   206→                }
   207→                Some('&') => {
   208→                    if self.peek_chars(2) == "&&" {
   209→                        tokens.push(Token::And);
   210→                        self.pos += 2;
   211→                        self.column += 2;
   212→                    } else {
   213→                        return Err(CompileError::LexerError(format!(
   214→                            "Unexpected character '&' at line {}, column {}",
   215→                            self.line, self.column
   216→                        )));
   217→                    }
   218→                }
   219→                Some('|') => {
   220→                    if self.peek_chars(2) == "||" {
   221→                        tokens.push(Token::Or);
   222→                        self.pos += 2;
   223→                        self.column += 2;
   224→                    } else {
   225→                        tokens.push(Token::Pipe);
   226→                        self.advance();
   227→                    }
   228→                }
   229→                Some('(') => {
   230→                    tokens.push(Token::LParen);
   231→                    self.advance();
   232→                }
   233→                Some(')') => {
   234→                    tokens.push(Token::RParen);
   235→                    self.advance();
   236→                }
   237→                Some('{') => {
   238→                    tokens.push(Token::LBrace);
   239→                    self.advance();
   240→                }
   241→                Some('}') => {
   242→                    tokens.push(Token::RBrace);
   243→                    self.advance();
   244→                }
   245→                Some('[') => {
   246→                    tokens.push(Token::LBracket);
   247→                    self.advance();
   248→                }
   249→                Some(']') => {
   250→                    tokens.push(Token::RBracket);
   251→                    self.advance();
   252→                }
   253→                Some(',') => {
   254→                    tokens.push(Token::Comma);
   255→                    self.advance();
   256→                }
   257→                Some('.') => {
   258→                    tokens.push(Token::Dot);
   259→                    self.advance();
   260→                }
   261→                Some(':') => {
   262→                    tokens.push(Token::Colon);
   263→                    self.advance();
   264→                }
   265→                Some(';') => {
   266→                    tokens.push(Token::Semicolon);
   267→                    self.advance();
   268→                }
   269→                Some(c) => {
   270→                    return Err(CompileError::LexerError(format!(
   271→                        "Unexpected character '{}' (U+{:04X}) at line {}, column {}",
   272→                        c, c as u32, self.line, self.column
   273→                    )))
   274→                }
   275→                None => break,
   276→            }
   277→        }
   278→
   279→        tokens.push(Token::Eof);
   280→        Ok(tokens)
   281→    }
   282→
   283→    fn current_char(&self) -> Option<char> {
   284→        if self.pos < self.input.len() {
   285→            Some(self.input[self.pos])
   286→        } else {
   287→            None
   288→        }
   289→    }
   290→
   291→    fn advance(&mut self) {
   292→        self.pos += 1;
   293→        self.column += 1;
   294→    }
   295→
   296→    fn peek_chars(&self, n: usize) -> String {
   297→        self.input[self.pos..std::cmp::min(self.pos + n, self.input.len())]
   298→            .iter()
   299→            .collect()
   300→    }
   301→
   302→    fn read_identifier_or_keyword(&mut self) -> Result<Token, CompileError> {
   303→        let mut s = String::new();
   304→
   305→        while self.current_char().map_or(false, |c| c.is_alphanumeric() || c == '_') {
   306→            s.push(self.current_char().unwrap());
   307→            self.advance();
   308→
   309→            // ✅ Check identifier length limit
   310→            if s.len() > MAX_IDENTIFIER_LENGTH {
   311→                return Err(CompileError::LexerError(
   312→                    format!("Identifier too long (max {} characters)", MAX_IDENTIFIER_LENGTH)
   313→                ));
   314→            }
   315→        }
   316→
   317→        Ok(match s.as_str() {
   318→            "fn" => Token::Fn,
   319→            "let" => Token::Let,
   320→            "if" => Token::If,
   321→            "else" => Token::Else,
   322→            "match" => Token::Match,
   323→            "return" => Token::Return,
   324→            "type" => Token::Type,
   325→            "mut" => Token::Mut,
   326→            "true" => Token::True,
   327→            "false" => Token::False,
   328→            _ => Token::Identifier(s),
   329→        })
   330→    }
   331→
   332→    fn read_number(&mut self) -> Result<Token, CompileError> {
   333→        let mut s = String::new();
   334→        let mut has_dot = false;
   335→
   336→        while let Some(c) = self.current_char() {
   337→            if c.is_numeric() {
   338→                s.push(c);
   339→                self.advance();
   340→            } else if c == '.' && !has_dot {
   341→                has_dot = true;
   342→                s.push(c);
   343→                self.advance();
   344→            } else {
   345→                break;
   346→            }
   347→
   348→            // ✅ Check number length limit
   349→            if s.len() > MAX_NUMBER_LENGTH {
   350→                return Err(CompileError::LexerError(
   351→                    format!("Number too large (max {} digits)", MAX_NUMBER_LENGTH)
   352→                ));
   353→            }
   354→        }
   355→
   356→        if s.is_empty() || s == "." {
   357→            return Err(CompileError::LexerError("Invalid number".to_string()));
   358→        }
   359→
   360→        if has_dot {
   361→            s.parse::<f64>()
   362→                .map(Token::Float)
   363→                .map_err(|_| CompileError::LexerError(format!("Invalid float: {}", s)))
   364→        } else {
   365→            s.parse::<i64>()
   366→                .map(Token::Integer)
   367→                .map_err(|_| CompileError::LexerError(format!("Invalid integer: {}", s)))
   368→        }
   369→    }
   370→
   371→    fn read_string(&mut self) -> Result<Token, CompileError> {
   372→        self.advance(); // Skip opening quote
   373→        let mut s = String::new();
   374→        let start_line = self.line;
   375→
   376→        while self.current_char() != Some('"') {
   377→            match self.current_char() {
   378→                Some('\\') => {
   379→                    self.advance();
   380→                    match self.current_char() {
   381→                        Some('n') => {
   382→                            s.push('\n');
   383→                            self.advance();
   384→                        }
   385→                        Some('t') => {
   386→                            s.push('\t');
   387→                            self.advance();
   388→                        }
   389→                        Some('r') => {
   390→                            s.push('\r');
   391→                            self.advance();
   392→                        }
   393→                        Some('"') => {
   394→                            s.push('"');
   395→                            self.advance();
   396→                        }
   397→                        Some('\\') => {
   398→                            s.push('\\');
   399→                            self.advance();
   400→                        }
   401→                        Some('0') => {
   402→                            s.push('\0');
   403→                            self.advance();
   404→                        }
   405→                        Some(c) => {
   406→                            return Err(CompileError::LexerError(format!(
   407→                                "Invalid escape sequence: \\{} at line {}",
   408→                                c, self.line
   409→                            )))
   410→                        }
   411→                        None => {
   412→                            return Err(CompileError::LexerError(
   413→                                "Unterminated string".to_string(),
   414→                            ))
   415→                        }
   416→                    }
   417→                }
   418→                Some('\n') => {
   419→                    self.line += 1;
   420→                    self.column = 1;
   421→                    s.push('\n');
   422→                    self.advance();
   423→                }
   424→                Some(c) => {
   425→                    s.push(c);
   426→                    self.advance();
   427→                }
   428→                None => {
   429→                    return Err(CompileError::LexerError(format!(
   430→                        "Unterminated string starting at line {}",
   431→                        start_line
   432→                    )))
   433→                }
   434→            }
   435→
   436→            // ✅ Check string length limit
   437→            if s.len() > MAX_STRING_LENGTH {
   438→                return Err(CompileError::LexerError(
   439→                    format!("String too long (max {} bytes)", MAX_STRING_LENGTH)
   440→                ));
   441→            }
   442→        }
   443→
   444→        self.advance(); // Skip closing quote
   445→        Ok(Token::String(s))
   446→    }
   447→
   448→    fn skip_line_comment(&mut self) {
   449→        while self.current_char() != Some('\n') && self.current_char() != None {
   450→            self.advance();
   451→        }
   452→        if self.current_char() == Some('\n') {
   453→            self.line += 1;
   454→            self.column = 1;
   455→            self.advance();
   456→        }
   457→    }
   458→}
