    use fv_lang::Lexer;
    use fv_lang::lexer::Token;

    // ── 헬퍼 ──────────────────────────────────────
    fn tokenize(src: &str) -> Vec<Token> {
        let lex = Lexer::new(src).expect("Lexer::new 실패");
        let mut toks = lex.tokenize().expect("tokenize 실패");
        // 마지막 Eof 제거
        if toks.last() == Some(&Token::Eof) {
            toks.pop();
        }
        toks
    }

    fn tokenize_err(src: &str) -> String {
        match Lexer::new(src) {
            Err(e) => return e.to_string(),
            Ok(lex) => match lex.tokenize() {
                Err(e) => e.to_string(),
                Ok(_) => panic!("에러를 기대했지만 성공함: {:?}", src),
            },
        }
    }

    // ── 1. 키워드 테스트 ───────────────────────────

    #[test]
    fn test_keyword_fn() {
        assert_eq!(tokenize("fn"), vec![Token::Fn]);
    }

    #[test]
    fn test_keyword_let() {
        assert_eq!(tokenize("let"), vec![Token::Let]);
    }

    #[test]
    fn test_keyword_if_then_else() {
        // FV-Lang: if / else 는 키워드, then 은 식별자 (렉서에 없음)
        let toks = tokenize("if else");
        assert_eq!(toks, vec![Token::If, Token::Else]);
    }

    #[test]
    fn test_keyword_match() {
        assert_eq!(tokenize("match"), vec![Token::Match]);
    }

    #[test]
    fn test_keyword_return() {
        assert_eq!(tokenize("return"), vec![Token::Return]);
    }

    #[test]
    fn test_keyword_type() {
        assert_eq!(tokenize("type"), vec![Token::Type]);
    }

    #[test]
    fn test_keyword_mut() {
        assert_eq!(tokenize("mut"), vec![Token::Mut]);
    }

    #[test]
    fn test_bool_literals() {
        assert_eq!(tokenize("true false"), vec![Token::True, Token::False]);
    }

    // ── 2. 식별자 테스트 ───────────────────────────

    #[test]
    fn test_identifier_simple() {
        assert_eq!(tokenize("hello"), vec![Token::Identifier("hello".into())]);
    }

    #[test]
    fn test_identifier_underscore_prefix() {
        assert_eq!(tokenize("_x"), vec![Token::Identifier("_x".into())]);
    }

    #[test]
    fn test_identifier_mixed() {
        assert_eq!(
            tokenize("myVar_123"),
            vec![Token::Identifier("myVar_123".into())]
        );
    }

    #[test]
    fn test_identifier_not_keyword() {
        // "letter" 는 키워드가 아니어서 Identifier
        assert_eq!(
            tokenize("letter"),
            vec![Token::Identifier("letter".into())]
        );
    }

    // ── 3. 숫자 테스트 ────────────────────────────

    #[test]
    fn test_integer_zero() {
        assert_eq!(tokenize("0"), vec![Token::Integer(0)]);
    }

    #[test]
    fn test_integer_positive() {
        assert_eq!(tokenize("42"), vec![Token::Integer(42)]);
    }

    #[test]
    fn test_integer_large() {
        assert_eq!(tokenize("1000000"), vec![Token::Integer(1_000_000)]);
    }

    #[test]
    fn test_float_basic() {
        assert_eq!(tokenize("3.14"), vec![Token::Float(3.14)]);
    }

    #[test]
    fn test_float_zero() {
        assert_eq!(tokenize("0.0"), vec![Token::Float(0.0)]);
    }

    // ── 4. 문자열 테스트 ──────────────────────────

    #[test]
    fn test_string_empty() {
        assert_eq!(tokenize(r#""""#), vec![Token::String("".into())]);
    }

    #[test]
    fn test_string_simple() {
        assert_eq!(
            tokenize(r#""hello""#),
            vec![Token::String("hello".into())]
        );
    }

    #[test]
    fn test_string_escape_newline() {
        assert_eq!(
            tokenize(r#""line\nbreak""#),
            vec![Token::String("line\nbreak".into())]
        );
    }

    #[test]
    fn test_string_escape_tab() {
        assert_eq!(
            tokenize(r#""tab\there""#),
            vec![Token::String("tab\there".into())]
        );
    }

    #[test]
    fn test_string_escape_quote() {
        assert_eq!(
            tokenize(r#""say \"hi\"""#),
            vec![Token::String("say \"hi\"".into())]
        );
    }

    #[test]
    fn test_string_escape_backslash() {
        assert_eq!(
            tokenize(r#""back\\slash""#),
            vec![Token::String("back\\slash".into())]
        );
    }

    // ── 5. 연산자 테스트 ──────────────────────────

    #[test]
    fn test_operators_arithmetic() {
        let toks = tokenize("+ - * / %");
        assert_eq!(
            toks,
            vec![
                Token::Plus,
                Token::Minus,
                Token::Star,
                Token::Slash,
                Token::Percent,
            ]
        );
    }

    #[test]
    fn test_operators_comparison() {
        let toks = tokenize("== != < <= > >=");
        assert_eq!(
            toks,
            vec![
                Token::Eq,
                Token::Ne,
                Token::Lt,
                Token::Le,
                Token::Gt,
                Token::Ge,
            ]
        );
    }

    #[test]
    fn test_operators_logical() {
        let toks = tokenize("&& || !");
        assert_eq!(toks, vec![Token::And, Token::Or, Token::Not]);
    }

    #[test]
    fn test_operator_assign() {
        assert_eq!(tokenize("="), vec![Token::Assign]);
    }

    #[test]
    fn test_operator_arrow() {
        assert_eq!(tokenize("->"), vec![Token::Arrow]);
    }

    #[test]
    fn test_operator_fat_arrow() {
        assert_eq!(tokenize("=>"), vec![Token::FatArrow]);
    }

    #[test]
    fn test_operator_pipe() {
        assert_eq!(tokenize("|"), vec![Token::Pipe]);
    }

    // ── 6. 구분자 테스트 ──────────────────────────

    #[test]
    fn test_delimiters() {
        let toks = tokenize("( ) { } [ ] , . : ;");
        assert_eq!(
            toks,
            vec![
                Token::LParen,
                Token::RParen,
                Token::LBrace,
                Token::RBrace,
                Token::LBracket,
                Token::RBracket,
                Token::Comma,
                Token::Dot,
                Token::Colon,
                Token::Semicolon,
            ]
        );
    }

    // ── 7. 복합 표현식 테스트 ─────────────────────

    #[test]
    fn test_let_binding() {
        let toks = tokenize("let x = 10");
        assert_eq!(
            toks,
            vec![
                Token::Let,
                Token::Identifier("x".into()),
                Token::Assign,
                Token::Integer(10),
            ]
        );
    }

    #[test]
    fn test_fn_declaration() {
        let toks = tokenize("fn add(a, b)");
        assert_eq!(
            toks,
            vec![
                Token::Fn,
                Token::Identifier("add".into()),
                Token::LParen,
                Token::Identifier("a".into()),
                Token::Comma,
                Token::Identifier("b".into()),
                Token::RParen,
            ]
        );
    }

    #[test]
    fn test_arrow_return_type() {
        let toks = tokenize("fn f() -> Int");
        assert_eq!(
            toks,
            vec![
                Token::Fn,
                Token::Identifier("f".into()),
                Token::LParen,
                Token::RParen,
                Token::Arrow,
                Token::Identifier("Int".into()),
            ]
        );
    }

    #[test]
    fn test_match_expr() {
        let toks = tokenize("match x { 1 => true }");
        assert_eq!(
            toks,
            vec![
                Token::Match,
                Token::Identifier("x".into()),
                Token::LBrace,
                Token::Integer(1),
                Token::FatArrow,
                Token::True,
                Token::RBrace,
            ]
        );
    }

    // ── 8. 주석 처리 테스트 ───────────────────────

    #[test]
    fn test_comment_skipped() {
        let toks = tokenize("// this is a comment\n42");
        assert_eq!(toks, vec![Token::Integer(42)]);
    }

    #[test]
    fn test_comment_inline() {
        let toks = tokenize("let x = 1 // assign");
        assert_eq!(
            toks,
            vec![
                Token::Let,
                Token::Identifier("x".into()),
                Token::Assign,
                Token::Integer(1),
            ]
        );
    }

    // ── 9. 공백/빈 입력 테스트 ────────────────────

    #[test]
    fn test_empty_input() {
        let lex = Lexer::new("").expect("Lexer::new 실패");
        let toks = lex.tokenize().expect("tokenize 실패");
        assert_eq!(toks, vec![Token::Eof]);
    }

    #[test]
    fn test_whitespace_only() {
        let lex = Lexer::new("   \n\t  ").expect("Lexer::new 실패");
        let toks = lex.tokenize().expect("tokenize 실패");
        assert_eq!(toks, vec![Token::Eof]);
    }

    // ── 10. 에러 케이스 테스트 ────────────────────

    #[test]
    fn test_error_unterminated_string() {
        let err = tokenize_err(r#""hello"#);
        assert!(
            err.contains("Unterminated") || err.contains("unterminated"),
            "에러 메시지에 'Unterminated' 포함 기대: {}",
            err
        );
    }

    #[test]
    fn test_error_invalid_escape() {
        let err = tokenize_err(r#""bad \q escape""#);
        assert!(
            err.contains("escape") || err.contains("Escape"),
            "에러 메시지에 'escape' 포함 기대: {}",
            err
        );
    }

    #[test]
    fn test_error_null_byte() {
        let err = tokenize_err("hello\0world");
        assert!(
            err.contains("null") || err.contains("Null"),
            "에러 메시지에 'null' 포함 기대: {}",
            err
        );
    }

    #[test]
    fn test_error_unexpected_char() {
        let err = tokenize_err("let x = @");
        assert!(
            err.contains("Unexpected") || err.contains("unexpected"),
            "에러 메시지에 'Unexpected' 포함 기대: {}",
            err
        );
    }

    #[test]
    fn test_error_lone_ampersand() {
        // & 단독은 에러 (&&는 And 토큰)
        let err = tokenize_err("a & b");
        assert!(
            err.contains("Unexpected") || err.contains("unexpected"),
            "에러 메시지에 'Unexpected' 포함 기대: {}",
            err
        );
    }

    // ── 11. get_tokens JSON 직렬화 테스트 ─────────

    #[test]
    fn test_get_tokens_json_simple() {
        let json = crate::get_tokens_json("let x = 42");
        assert!(json.contains("\"success\":true"), "성공 응답 기대: {}", json);
        assert!(json.contains("Let"), "Let 토큰 기대: {}", json);
        assert!(json.contains("42"), "42 포함 기대: {}", json);
    }

    #[test]
    fn test_get_tokens_json_error() {
        let json = crate::get_tokens_json(r#""unterminated"#);
        assert!(json.contains("\"success\":false"), "실패 응답 기대: {}", json);
        assert!(json.contains("error"), "error 필드 기대: {}", json);
    }
}

