   184→fn parse_ast(code: &str) -> String {
   185→    let lexer = match fv_lang::Lexer::new(code) {
   186→        Ok(l) => l,
   187→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   188→    };
   189→    let tokens = match lexer.tokenize() {
   190→        Ok(t) => t,
   191→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   192→    };
   193→    let parser = match fv_lang::Parser::new(tokens) {
   194→        Ok(p) => p,
   195→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   196→    };
   197→    match parser.parse() {
   198→        Ok(ast) => {
   199→            let debug_str = format!("{:#?}", ast);
   200→            format!(r#"{{"success":true,"ast":{}}}"#, json_str(&debug_str))
   201→        }
   202→        Err(e) => format!(r#"{{"success":false,"error":"{}"}}"#, e),
   203→    }
   204→}
   205→
   206→fn json_str(s: &str) -> String {
   207→    let mut out = String::with_capacity(s.len() + 2);
   208→    out.push('"');
   209→    for c in s.chars() {
   210→        match c {
   211→            '\\' => out.push_str("\\\\"),
   212→            '"'  => out.push_str("\\\""),
   213→            '\n' => out.push_str("\\n"),
   214→            '\r' => out.push_str("\\r"),
   215→            '\t' => out.push_str("\\t"),
   216→            '\x00'..='\x1f' => {
   217→                out.push_str(&format!("\\u{:04x}", c as u32));
   218→            }
   219→            _ => out.push(c),
   220→        }
   221→    }
   222→    out.push('"');
   223→    out
   224→}
